<x-client.layout.app title="Ticket Details"><section class="page-head"><div><h1>Ticket Details</h1></div><a class="back-link" href="{{ route('client.tickets.index') }}"><i class="fa-solid fa-arrow-left"></i></a></section><div class="detail-card"><div class="detail-grid"><div class="detail-item"><span>Ticket</span><strong>#{{ $ticket->ticket_number }}</strong></div><div class="detail-item"><span>Status</span><strong>{{ method_exists($ticket->status,'label')?$ticket->status->label():ucfirst($ticket->status->value ?? $ticket->status) }}</strong></div><div class="detail-item full"><span>Subject</span><strong>{{ $ticket->subject }}</strong></div><div class="detail-item"><span>Priority</span><strong>{{ method_exists($ticket->priority,'label')?$ticket->priority->label():ucfirst($ticket->priority->value ?? $ticket->priority) }}</strong></div><div class="detail-item"><span>Created</span><strong>{{ $ticket->created_at?->format('d M Y') }}</strong></div><div class="detail-item full"><span>Message</span><strong>{{ $ticket->message }}</strong></div></div><div class="form-actions"><a class="secondary-btn" href="{{ route('client.tickets.chat',$ticket) }}"><i class="fa-regular fa-comments"></i> Chat</a><a class="primary-btn" href="{{ route('client.tickets.edit',$ticket) }}"><i class="fa-regular fa-pen-to-square"></i> Edit Ticket</a></div></div></x-client.layout.app>